{{ config(materialized='view') }}

{# Build a staging model over the raw orders source #}
{% set regions = ['us', 'eu', 'apac'] %}

with source as (
    select * from {{ source('shop', 'orders') }}
),

renamed as (
    select
        order_id,
        customer_id,
        lower(region) as region,
        -- reusable macro turns integer cents into a dollar numeric
        {{ cents_to_dollars('amount_cents') }} as amount_usd,
        {% for r in regions -%}
        case when lower(region) = '{{ r }}' then 1 else 0 end as is_{{ r }}
        {%- if not loop.last %},{% endif %}
        {% endfor %}
    from source
)

select * from renamed

{% macro cents_to_dollars(column_name, scale=2) %}
    ({{ column_name }} / 100)::numeric(16, {{ scale }})
{% endmacro %}


{% macro grant_select(role='reporter') %}

    {% set relation = this %}
    {% set sql %}
        grant select on {{ relation }} to role {{ role }}
    {% endset %}

    {% if execute %}
        {% do run_query(sql) %}
        {{ log('Granted select on ' ~ relation ~ ' to ' ~ role, info=True) }}
    {% endif %}

{% endmacro %}
